import {upgradeRoster,employeeProgress,progressTotals,inScope} from './progress.js';
export const KEY='mmsu-eipcr-v1', SESSION='mmsu-eipcr-session';
export const CATEGORIES=['Strategic','Core','Support'];
export const ROLES=['Administrator','HR Personnel','President','Vice President','Dean','Department Head','Teaching Employee','Non-Teaching Employee'];
export const STAGES=['Department Head','Dean','HR Personnel','Vice President','President','Completed'];
export const employee=u=>u?.role?.endsWith('Employee');
export const uid=()=>globalThis.crypto?.randomUUID?.()||String(Date.now()+Math.random());
export const now=()=>new Date().toISOString();
export function rowAverage(row){const a=['q','e','t'].map(k=>row[k]);return a.every(v=>v!==''&&v!=null&&Number.isFinite(+v)&&+v>=1&&+v<=5)?a.reduce((s,v)=>s+ +v,0)/3:null;}
export function rating(record,settings){const categories=CATEGORIES.map((c,i)=>{const values=record.rows.filter(r=>r.category===c&&r.applicable).map(rowAverage).filter(v=>v!==null);return {name:c,weight:settings.weights[i],average:values.length?values.reduce((s,v)=>s+v,0)/values.length:null};});const complete=categories.every(c=>c.weight===0||c.average!==null);const total=complete?categories.reduce((s,c)=>s+(c.average||0)*c.weight/100,0):null;return {categories,total,label:total===null?'Not yet rated':(settings.scale.find(s=>total>=s.min)?.label||'Poor')};}
export function templateRows(type){const teaching=type==='Teaching';return CATEGORIES.map((category,i)=>({id:uid(),category,applicable:true,program:i===0?(teaching?'Higher Education Program':'Administrative Services'):'',indicatorType:i===0?'Output indicator':'Function',indicator:teaching?['Contribute to program accreditation','Prepare and deliver assigned courses','Participate in university committees'][i]:['Improve office service turnaround','Process and maintain accurate office records','Participate in professional development'][i],target:teaching?['Prepare evidence for one accreditation area','Update syllabi for all assigned courses','Participate in one committee'][i]:['Document one improved service procedure','Process 100 requests within service standards','Complete one relevant training'][i],actual:'',q:'',e:'',t:'',remarks:''}));}
export function makeRecord(user,period,settings){return {id:uid(),owner:user.id,name:user.name,position:user.position,unit:user.unit,department:user.department,type:user.type,period,status:'Draft',created:now(),updated:now(),commitment:'I commit to deliver and agree to be evaluated on the attainment of the following targets in accordance with the indicated measures.',development:'',rows:templateRows(user.type),history:[],submissions:[],ratingSettings:structuredClone(settings)};}
export function seed(){const units=[{id:'coe',name:'College of Engineering',departments:['Computer Engineering','Civil Engineering']},{id:'admin',name:'Administrative Services',departments:['Records Office','Finance Office']}];const users=ROLES.map((role,i)=>({id:'u'+i,name:['Alex Rivera','Mika Santos','Gabriel Reyes','Isabel Cruz','Elena Flores','Daniel Ramos','Sofia Mendoza','Luis Navarro'][i],email:['admin','hr','president','vp','dean','head','teaching','nonteaching'][i]+'@demo.mmsu.edu.ph',password:'Demo@2026',role,position:['System Administrator','HR Officer','University President','Vice President','College Dean','Department Chair','Assistant Professor','Administrative Officer'][i],unit:i===7?'Administrative Services':'College of Engineering',department:i===7?'Records Office':'Computer Engineering',type:i===7?'Non-Teaching':'Teaching',active:true}));
// A second pair of reviewers demonstrates assignment boundaries for office staff.
users.push({...users[5],id:'head-office',name:'Clara Dizon',email:'head.office@demo.mmsu.edu.ph',unit:'Administrative Services',department:'Records Office'},{...users[4],id:'dean-office',name:'Rafael Lim',email:'dean.office@demo.mmsu.edu.ph',unit:'Administrative Services',department:'Records Office'});
const settings={weights:[45,45,10],scale:[{min:4.5,label:'Outstanding'},{min:3.5,label:'Very Satisfactory'},{min:2.5,label:'Satisfactory'},{min:1.5,label:'Unsatisfactory'},{min:1,label:'Poor'}]};const periods=[{id:'2026-2',name:'July – December 2026',start:'2026-07-01',end:'2026-12-31',active:true},{id:'2026-1',name:'January – June 2026',start:'2026-01-01',end:'2026-06-30',active:false}];const records=[];
for(let i=0;i<8;i++){
 const owner=users[i%2?7:6],r=makeRecord(owner,periods[i<6?0:1].id,settings);
 r.id='IPCR-'+String(1001+i);r.status=['Draft','Department Head','Dean','HR Personnel','Vice President','President','Completed','Returned'][i];
 r.created=`2026-${i<6?'09':'06'}-${String(10+i).padStart(2,'0')}T08:30:00.000Z`;r.updated=r.created;
 r.rows.forEach((row,j)=>{row.actual=['Evidence prepared and filed','Targets delivered within the period','Activity completed and documented'][j];row.q=3+(i%3);row.e=4;row.t=4;});
 r.history=[{at:r.created,actor:owner.name,role:owner.role,action:'Created sample record',comment:'Fictional demonstration record.'}];
 if(r.status!=='Draft'){
  r.submissions=[{at:r.created,rows:structuredClone(r.rows),commitment:r.commitment,development:r.development,ratingSettings:structuredClone(settings)}];
  r.history.push({at:r.created,actor:owner.name,role:owner.role,action:'Submitted',comment:''});
  const approved=r.status==='Returned'?2:STAGES.indexOf(r.status);
  for(let j=0;j<approved;j++){
   const role=STAGES[j];const reviewer=users.find(u=>u.role===role&&(role!=='Department Head'||u.department===r.department)&&(role!=='Dean'||u.unit===r.unit));
   r.history.push({at:new Date(new Date(r.created).getTime()+(j+1)*3600000).toISOString(),actor:reviewer.name,role,action:role==='President'?'Final approval · Completed':'Approved and forwarded',comment:'Sample review completed.'});
  }
 }
 if(r.status==='Returned')r.history.push({at:new Date(new Date(r.created).getTime()+3*3600000).toISOString(),actor:users[1].name,role:'HR Personnel',action:'Returned for correction',comment:'Please specify the number of requests completed and the completion dates.'});
 r.updated=r.history.at(-1).at;records.push(r);
}
return upgradeRoster({version:1,users,units,periods,settings,records,notifications:[{id:uid(),user:'u6',text:'Your July – December evaluation period is open.',record:null,at:now(),read:false}]},true);}
export function visibleRecords(db,user){return db.records.filter(r=>{const owner=db.users.find(u=>u.id===r.owner)||r;return inScope(user,owner)&&(employee(user)||r.status!=='Draft');});}
export const queue=(db,user)=>visibleRecords(db,user).filter(r=>r.status===user.role);
export function canEdit(user,r){return employee(user)&&r.owner===user.id&&['Draft','Returned'].includes(r.status);}
export function validateRecord(r,submit=false){const errors=[];if(!r.name?.trim()||!r.position?.trim()||!r.unit||!r.department||!r.period||!r.commitment?.trim())errors.push('Complete the employee details, period, and commitment.');for(const row of r.rows){if(!row.applicable)continue;for(const k of ['q','e','t'])if(row[k]!==''&&row[k]!=null&&(!Number.isFinite(+row[k])||+row[k]<1||+row[k]>5))errors.push('Q, E, and T must be numbers from 1 to 5.');if(submit&&(!row.indicator.trim()||!row.target.trim()))errors.push('Each applicable row needs an indicator and a target.');}return [...new Set(errors)];}
function notify(db,r,text){const assigned=db.users.find(u=>u.id===r.owner)||r;const ids=new Set([r.owner,...db.users.filter(u=>u.active&&u.role===r.status&&(u.role!=='Department Head'||u.unit===assigned.unit&&u.department===assigned.department)&&(u.role!=='Dean'||u.unit===assigned.unit)).map(u=>u.id)]);for(const user of ids)db.notifications.push({id:uid(),user,text,record:r.id,at:now(),read:false});}
export function transition(db,user,id,action,comment=''){const r=db.records.find(x=>x.id===id);if(!r)throw Error('Record not found.');const at=now();let text;if(action==='submit'){if(!canEdit(user,r))throw Error('Only the owner can submit an editable record.');const errors=validateRecord(r,true);if(errors.length)throw Error(errors.join(' '));if(!user.periodIds?.includes(r.period))throw Error('You are not assigned to this evaluation period. Contact the administrator.');r.unit=user.unit;r.department=user.department;r.type=user.type;const resubmit=r.status==='Returned';r.ratingSettings=structuredClone(db.settings);r.submissions.push({at,name:r.name,position:r.position,unit:r.unit,department:r.department,period:r.period,commitment:r.commitment,development:r.development,rateeDate:r.rateeDate||'',discussionDate:r.discussionDate||'',mfo:structuredClone(r.mfo||{}),rows:structuredClone(r.rows),ratingSettings:structuredClone(r.ratingSettings)});r.status='Department Head';text=resubmit?'Resubmitted':'Submitted';}else{if(!queue(db,user).some(x=>x.id===id))throw Error('This record is not assigned to your review queue.');if(action==='return'){if(!['Department Head','Dean','HR Personnel'].includes(user.role))throw Error('This role cannot return a record.');if(!comment.trim())throw Error('A correction comment is required.');r.status='Returned';text='Returned for correction';}else if(action==='approve'){r.status=STAGES[STAGES.indexOf(user.role)+1];if(r.status==='Completed')r.finalRating={...rating(r,r.ratingSettings||db.settings),approvedAt:at};text=r.status==='Completed'?'Final approval · Completed':'Approved and forwarded';}else throw Error('Unknown action.');}r.updated=at;r.history.push({at,actor:user.name,role:user.role,action:text,comment:comment.trim()});notify(db,r,`${r.name}: ${text}. ${comment.trim()}`);return r;}
export function filterRecords(records,filters){return records.filter(r=>['period','unit','department','type','status'].every(k=>!filters[k]||r[k]===filters[k])&&(!filters.search||`${r.name} ${r.id} ${r.department}`.toLowerCase().includes(filters.search.toLowerCase())));}
export function compliance(db,filters){const t=progressTotals(employeeProgress(db,{role:'HR Personnel',active:true},filters));return {expected:t.expected,submitted:t.submitted,percent:t.submissionPercent};}
export function csv(records,db){const fields=['Record ID','Employee','Employee type','College / office','Department','Period','Status','Overall rating','Adjectival rating'];const cell=v=>'"'+String(v??'').replace(/^[=+@\-]/,"'$&").replaceAll('"','""')+'"';return '\uFEFF'+[fields,...records.map(r=>{const s=rating(r,['Draft','Returned'].includes(r.status)?db.settings:(r.ratingSettings||db.settings));return [r.id,r.name,r.type,r.unit,r.department,db.periods.find(p=>p.id===r.period)?.name,r.status,s.total?.toFixed(2)??'',s.label];})].map(row=>row.map(cell).join(',')).join('\r\n');}


